    let j = tap(uv + vec2f( 2.0 * t.x,  0.0));
    let k = tap(uv + vec2f(-2.0 * t.x,  2.0 * t.y));
    let l = tap(uv + vec2f( 0.0,        2.0 * t.y));
    let m = tap(uv + vec2f( 2.0 * t.x,  2.0 * t.y));

